import React from "react"
import algoliasearch from "algoliasearch"
import ToolsFilter from "./ToolsFilter"
import { ToolCardInterface } from "@/lib/types"

interface AlgoliaSearchProps {
  searchParams: {
    query?: string
  }
}

export const getTools = async (text: string): Promise<ToolCardInterface[]> => {
  if (!text) {
    return []
  }
  const client = algoliasearch(
    process.env.NEXT_PUBLIC_ALGOLIA_APP_ID!,
    process.env.NEXT_PUBLIC_ALGOLIA_SEARCH_KEY!
  )

  const index = client.initIndex("toolData")
  const { hits } = await index.search<ToolCardInterface>(text, {
    hitsPerPage: 20,
  })

  return hits
}

const AlgoliaSearch: React.FC<AlgoliaSearchProps> = async () => {
  return (
    <div className="mx-auto w-full max-w-4xl px-4 md:px-0">
      <ToolsFilter />
    </div>
  )
}

export default AlgoliaSearch

"use client"

import * as React from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { Search } from "lucide-react"

export default function SearchBar() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [searchValue, setSearchValue] = React.useState(
    searchParams.get("query") || ""
  )

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchValue(e.target.value)
  }

  const updateSearchQuery = React.useCallback(
    (query: string) => {
      const params = new URLSearchParams(searchParams)
      const hasFilters =
        params.has("categories") || params.has("tags") || params.has("sort")

      if (query) {
        if (hasFilters) {
          params.delete("categories")
          params.delete("tags")
          params.delete("sort")
        }
        params.set("query", query)
      } else {
        params.delete("query")
      }

      router.push(`/tools?${params.toString()}`)
    },
    [router, searchParams]
  )

  React.useEffect(() => {
    const debounceSearch = setTimeout(() => {
      updateSearchQuery(searchValue.trim())
    }, 300) // Increased debounce time for better performance

    return () => clearTimeout(debounceSearch)
  }, [searchValue, updateSearchQuery])

  // Reset search value when filters change
  React.useEffect(() => {
    const hasFilters =
      searchParams.has("categories") ||
      searchParams.has("tags") ||
      searchParams.has("sort")
    if (hasFilters && searchValue) {
      setSearchValue("")
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams])

  return (
    <div className="relative w-full grow">
      <input
        type="text"
        placeholder="Search tools..."
        value={searchValue}
        onChange={handleSearchChange}
        className="h-12 w-full rounded-full border border-white/20 bg-[#141414] pl-12 pr-4 transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-white/30"
      />
      <Search className="absolute left-4 top-1/2 size-5 -translate-y-1/2 text-neutral-400" />
    </div>
  )
}

